def get_compatibility_question_set(seed: str):
    """
    Return one question set, chosen deterministically from the given seed.
    Both users in a session get the same set because the seed is the session id.
    """
    idx = sum(ord(c) for c in seed) % len(COMPATIBILITY_QUESTION_SETS)
    return COMPATIBILITY_QUESTION_SETS[idx]